import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = [int(x) for x in data[1:1 + n]]
    best = 1
    for i in range(n):
        seen = set()
        lo = hi = a[i]
        for j in range(i, n):
            v = a[j]
            if v in seen:
                break
            seen.add(v)
            if v < lo:
                lo = v
            if v > hi:
                hi = v
            if hi - lo == j - i and j - i + 1 > best:
                best = j - i + 1
    print(best)

